\label{cor:3-mfd-linear}
The fundamental group of every compact $3$-manifold is linear over
$\mathbb C$.

\label{lem:scalar-tensor}
Let $A\in\operatorname{GL}_r(k)$ and $B\in\operatorname{GL}_s(k)$, where $r,s\geq1$.  If $A\otimes B$ is
a scalar matrix, then both $A$ and $B$ are scalar matrices.

\label{lem:pointed-scaling}
Let $A=I_d+N\in\operatorname{GL}_d(k)$ with $N^2=0$, and let $c\in k^\times$.  There is a
$k$-linear automorphism $S_c\in\operatorname{GL}(\operatorname{Mat}_d(k))$ such that, for every $r\in k$,
\begin{equation}
\label{eq:pointed-scaling}
S_c(A)=A,
\qquad
\tau_A\circ S_c=\tau_A,
\qquad
S_cU_A(r)S_c^{-1}=U_A(cr).
\end{equation}

\label{lem:arbitrary-gluing}
For the gluing matrix $A$ in \eqref{eq:gluing-matrix}, there are rational
numbers $\mu_-,\mu_+$ and an $\mathbb R$-linear isomorphism
\[
Q_e^0\colon V_{v_-}\longrightarrow V_{v_+}
\]
such that, for every $h\in G_{|e|}$,
\begin{equation}
\label{eq:gluing-intertwining}
Q_e^0\sigma_{v_-}(\iota_e(h))
 =\sigma_{v_+}(\iota_{\bar e}(h))Q_e^0,
\end{equation}
and
\begin{equation}
\label{eq:gluing-pointed}
Q_e^0Z_{a_-}^0=Z_{a_+}^0,
\qquad
\lambda_{a_+}^0Q_e^0=\lambda_{a_-}^0.
\end{equation}
More precisely:
\begin{enumerate}[label=\textup{(\alph*)}]
\item if $b\neq0$, take
\begin{equation}
\label{eq:mu-b-nonzero}
\mu_-:=\frac ab,
\qquad
\mu_+:=-\frac db,
\end{equation}
and in standardized coordinates define
\begin{equation}
\label{eq:Qhat-b-nonzero}
\widehat Q_e^0(P,Q):=
\bigl(S_bQ,S_{-\Delta/b}P\bigr);
\end{equation}
\item if $b=0$, take
\begin{equation}
\label{eq:mu-b-zero}
\mu_-:=\frac cd,
\qquad
\mu_+:=0,
\end{equation}
and define
\begin{equation}
\label{eq:Qhat-b-zero}
\widehat Q_e^0(P,Q):=
\bigl(S_aP,S_dQ\bigr).
\end{equation}
\end{enumerate}
Here $S_r$ is any automorphism supplied by \Cref{lem:pointed-scaling}, applied
to $K$, for the indicated nonzero scalar $r$.  In both cases one may take
\begin{equation}
\label{eq:Q-unstandardize}
Q_e^0:=J_+^{-1}\widehat Q_e^0J_-.
\end{equation}

\label{lem:peripheral-detector}
For every $g\in G_v$,
\begin{equation}
\label{eq:peripheral-detector}
\lambda_{v,i}^0\bigl(\sigma_v(g)Z_{v,i}^0\bigr)=1
\quad\Longleftrightarrow\quad
g\in H_{v,i}.
\end{equation}
